import subprocess,os,signal,ast,json,time
E=os.path.abspath('./executable')
def run(args,timeout=3):
 p=subprocess.Popen([E]+args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
 try:o,e=p.communicate(timeout=timeout);return p.returncode,o.decode(errors='replace'),e.decode(errors='replace')
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate();return 'TIMEOUT',o.decode(errors='replace'),e.decode(errors='replace')
def observe(seed=1,w=5,h=5,n=1,players=1,mode='bad',extra=[]):
 cmd=f'python3 .scratch/probe.py .scratch/map-probe.txt {mode}'
 args=['-q','-r','-s',str(seed),'-d',f'{w} {h}','-n',str(n)]+extra+[cmd]*players
 rc,o,e=run(args)
 d={'rc':rc,'out':o,'err':e}
 if rc==0:
  lines=[ast.literal_eval(x) for x in open('.scratch/map-probe.txt').read().splitlines()[:4]]
  width,height=map(int,lines[1].split()); vals=list(map(int,lines[3].split())); owners=[];i=0
  while len(owners)<width*height:
   k,p=vals[i:i+2];i+=2;owners.extend([p]*k)
  d.update(w=width,h=height,prod=list(map(int,lines[2].split())),owners=owners,strength=vals[i:])
 return d
if __name__=='__main__':
 for n in range(1,7):
  for w,h in [(5,5),(7,11),(10,8),(25,25)]:
   d=observe(w=w,h=h,n=n)
   print('sizing',n,w,h,d.get('w'),d.get('h'), 'starts',[(j%d['w'],j//d['w'],v,d['strength'][j],d['prod'][j]) for j,v in enumerate(d.get('owners',[])) if v], 'rc',d['rc'],flush=True)
 for seed in [1,2,3,42,123]:
  for size in [1,2,3,4,5,6,8]:
   d=observe(seed=seed,w=size,h=size)
   print('map',seed,size,json.dumps(d),flush=True)
