#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <random>
#include <vector>

struct Cell { int owner, strength, production; };
namespace {
#ifdef TERRAIN_FLOAT
using Real = float;
#else
using Real = double;
#endif
using Field = std::vector<Real>;
struct Noise { Real weight; Field field; };
void smooth(Field &v, int w, int h, Real center) {
    Field next(v.size());
    for (int y=0; y<h; ++y) for (int x=0; x<w; ++x) {
        next[y*w+x]=(center*v[y*w+x]+v[y*w+(x+w-1)%w]+v[y*w+(x+1)%w]
            +v[((y+h-1)%h)*w+x]+v[((y+1)%h)*w+x])/(center+4);
    }
    v.swap(next);
}
Noise noise(int w, int h, std::mt19937 &rng) {
    std::uniform_real_distribution<double> uniform(0.0,1.0);
    Real weight=std::pow(uniform(rng),1.5);
    if (w==1 && h==1) return {weight,Field(1,1)};
    int nx=std::min(w,4), ny=std::min(h,4);
    std::vector<int> widths(nx), heights(ny);
    for(int i=0;i<nx;++i) widths[i]=w/nx+(i<w%nx);
    for(int i=0;i<ny;++i) heights[i]=h/ny+(i<h%ny);
    std::vector<Noise> children;
    Field weights;
    for(int j=0;j<ny;++j) for(int i=0;i<nx;++i) {
        children.push_back(noise(widths[i],heights[j],rng));
        weights.push_back(children.back().weight);
    }
    smooth(weights,nx,ny,12);
    Field result(w*h);
    int offsetY=0, index=0;
    for(int j=0;j<ny;++j) {
        int offsetX=0;
        for(int i=0;i<nx;++i,++index) {
            for(int y=0;y<heights[j];++y) for(int x=0;x<widths[i];++x)
                result[(offsetY+y)*w+offsetX+x]=children[index].field[y*widths[i]+x]*weights[index];
            offsetX+=widths[i];
        }
        offsetY+=heights[j];
    }
    return {weight,std::move(result)};
}
}
extern "C" {
void free_map(Cell *map) { std::free(map); }
int generate_map(uint32_t seed,int players,int requestedW,int requestedH,int actualPlayers,Cell **out,int *ow,int *oh) {
    std::mt19937 rng(seed);
    bool horizontal=rng()%2;
    int a=(players==4||players==6)?players/2:players;
    int b=(players==4||players==6)?2:1;
    int roundX=a,roundY=a;
    if(b==2) { roundX=a; roundY=players*2; if(!horizontal)std::swap(roundX,roundY); }
    int w=(uint16_t)requestedW, h=(uint16_t)requestedH;
    w=w/roundX*roundX;h=h/roundY*roundY;
    if(w<=0||h<=0 || w>4096||h>4096 || (long long)w*h>4000000) return -1;
    int bw=w/(horizontal?a:b), bh=h/(horizontal?b:a);
    if(bw<1||bh<1) return -1;
    auto prod=noise(bw,bh,rng).field;
    auto str=noise(bw,bh,rng).field;
    int shift=players==6?0:rng()%a;
    int maxProduction=6+rng()%10, maxStrength=150+rng()%106;
    Field fullP(w*h),fullS(w*h);
    std::vector<int> owners(w*h);
    for(int y=0;y<h;++y) for(int x=0;x<w;++x) {
        int i,j,xx,yy,owner;
        if(horizontal) {
            i=x/bw;xx=x%bw;
            int movedY=(y+i*(h/a)*shift)%h;j=movedY/bh;yy=movedY%bh;
            if(a==2&&i==1)xx=bw-1-xx;
            if(b==2&&j==1)yy=bh-1-yy;
            owner=j*a+i+1;
        } else {
            i=y/bh;yy=y%bh;
            int movedX=(x+i*(w/a)*shift)%w;j=movedX/bw;xx=movedX%bw;
            if(a==2&&i==1)yy=bh-1-yy;
            if(b==2&&j==1)xx=bw-1-xx;
            owner=i*b+j+1;
        }
        int pos=y*w+x;
        fullP[pos]=prod[yy*bw+xx];fullS[pos]=str[yy*bw+xx];
        if(xx==bw/2 && yy==bh/2 && owner<=actualPlayers) owners[pos]=owner;
    }
    for(int i=0;i<std::min(w,h)/5+1;++i) {
        smooth(fullP,w,h,8);smooth(fullS,w,h,8);
    }
    Real mp=*std::max_element(fullP.begin(),fullP.end()), ms=*std::max_element(fullS.begin(),fullS.end());
    Cell *map=(Cell*)std::malloc(sizeof(Cell)*w*h);
    if(!map)return -1;
    for(int i=0;i<w*h;++i) {
        map[i]={owners[i],(int)std::round(fullS[i]/ms*maxStrength),(int)std::round(fullP[i]/mp*maxProduction)};
        if(owners[i] && map[i].production<1)map[i].production=1;
    }
    *out=map;*ow=w;*oh=h;
    return 0;
}
void advance_map(Cell *map,int w,int h,int players,const uint8_t *moves) {
    int size=w*h;
    std::vector<std::array<int,7>> force(size);
    std::vector<std::array<bool,7>> present(size);
    for(int y=0;y<h;++y) for(int x=0;x<w;++x) {
        int i=y*w+x,owner=map[i].owner;
        present[i][owner]=true;
        if(!owner) { force[i][0]=map[i].strength;continue; }
        int dir=moves[i],xx=x,yy=y;
        if(dir==1)yy=(y+h-1)%h;
        if(dir==2)xx=(x+1)%w;
        if(dir==3)yy=(y+1)%h;
        if(dir==4)xx=(x+w-1)%w;
        int dest=yy*w+xx;
        int strength=map[i].strength;
        if(dir==0)strength=std::min(255,strength+map[i].production);
        force[dest][owner]+=strength;
        present[dest][owner]=true;
    }
    // All movement occurs before simultaneous attacks.
    for(auto &v:force)for(int p=1;p<=players;++p)v[p]=std::min(255,v[p]);
    for(int y=0;y<h;++y) for(int x=0;x<w;++x) {
        int i=y*w+x;
        int neighbors[4]={y*w+(x+w-1)%w,y*w+(x+1)%w,((y+h-1)%h)*w+x,((y+1)%h)*w+x};
        int owner=0,strength=0;
        for(int p=0;p<=players;++p) if(present[i][p]) {
            int damage=0;
            for(int q=0;q<=players;++q)if(q!=p)damage+=force[i][q];
            if(p)for(int j:neighbors)for(int q=1;q<=players;++q)if(q!=p)damage+=force[j][q];
            int left=force[i][p]-damage;
            if(left>0 || (left==0 && damage==0)) { owner=p;strength=std::min(255,left); }
        }
        map[i].owner=owner;map[i].strength=strength;
    }
}
}
