    for(int y=0;y<h;++y) for(int x=0;x<w;++x) {
        int i=y*w+x;
        int neighbors[4]={y*w+(x+w-1)%w,y*w+(x+1)%w,((y+h-1)%h)*w+x,((y+1)%h)*w+x};
        int owner=0,strength=0;
        for(int p=0;p<=players;++p) if(present[i][p]) {
            int damage=0;
            for(int q=0;q<=players;++q)if(q!=p)damage+=force[i][q];
            if(p)for(int j:neighbors)for(int q=1;q<=players;++q)if(q!=p)damage+=force[j][q];
            int left=force[i][p]-damage;
            if(left>0 || (left==0 && damage==0)) { owner=p;strength=std::min(255,left); }
        }
        map[i].owner=owner;map[i].strength=strength;
    }
}
