ROOT = os.path.dirname(os.path.realpath(__file__))
if os.path.basename(ROOT) == 'src':
    ROOT = os.path.dirname(ROOT)
sys.path.insert(0, os.path.join(ROOT, 'src'))
from helptext import WHERE

USAGE = ('[-i <path to directory>] [-s <positive integer>] '
         '[-d <a string containing two space-seprated positive integers>] '
         '[-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version] '
         '[-h] <Array of strings> ...')
OPTIONS = {'i': 'replaydirectory', 's': 'seed', 'd': 'dimensions', 'n': 'nplayers',
           'r': 'noreplay', 't': 'timeout', 'o': 'override', 'q': 'quiet', 'h': 'help'}
SEPARATOR = '-' * 77 + '\n'


def usage():
    prog = sys.argv[0]
    return textwrap.fill(USAGE, width=75, initial_indent='   ' + prog + '  ',
                         subsequent_indent=' ' * (len(prog) + 5),
                         break_long_words=False, break_on_hyphens=False)


def parse_error(flag, message):
    arg = '-' + flag + ' (--' + OPTIONS[flag] + ')'
    sys.stderr.write('PARSE ERROR: Argument: ' + arg + '\n             ' + message +
                     '\n\nBrief USAGE: \n' + usage() +
                     '\n\nFor complete USAGE and HELP type: \n   ' + sys.argv[0] + ' --help\n\n')
    raise SystemExit(1)


def integer(value):
    if not re.fullmatch(r'\s*[+-]?[0-9]+', value, re.ASCII):
        raise ValueError()
    x = int(value)
    if x < -4294967295 or x > 4294967295:
        raise ValueError()
    return x & 0xffffffff


def arguments():
    result = dict(i='./', s=0, d=(0, 0), n=1, r=False, t=False, o=False, q=False)
    used = set()
    bots = []
    args = sys.argv[1:]
    ignore = False
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if not ignore and arg in ('--', '--ignore_rest'):
            ignore = True
            continue
        if not ignore and arg == '--version':
            print('\n' + sys.argv[0] + '  version: 1.2\n')
            raise SystemExit(0)
        flag = None
        if not ignore:
            for short, long in OPTIONS.items():
                if arg in ('-' + short, '--' + long):
                    flag = short
                    break
        if flag is None and not ignore and arg.startswith('-') and not arg.startswith('--') and len(arg) > 2:
            group = arg[1:]
            if all(x in 'rtoq h'.replace(' ', '') for x in group):
                for c in group:
                    if c == 'h':
                        print('\nUSAGE: \n\n' + usage() + '\n\n\n' + WHERE, end='')
                        raise SystemExit(0)
                    if c in used:
                        parse_error(c, 'Argument already set!')
                    used.add(c)
                    result[c] = True
                continue
        if flag is None:
            bots.append(arg)
            continue
        if flag == 'h':
            print('\nUSAGE: \n\n' + usage() + '\n\n\n' + WHERE, end='')
            raise SystemExit(0)
        if flag in used:
            parse_error(flag, 'Argument already set!')
        used.add(flag)
        if flag in 'rtoq':
            result[flag] = True
        else:
            if i >= len(args):
                parse_error(flag, 'Missing a value for this argument!')
            value = args[i]
            i += 1
            try:
                if flag in 'sn':
                    result[flag] = integer(value)
                elif flag == 'd':
                    m = re.fullmatch(r'\s*([+-]?[0-9]+)\s+([+-]?[0-9]+)', value, re.ASCII)
                    if not m:
                        raise ValueError()
                    result[flag] = (integer(m[1]), integer(m[2]))
                else:
                    result[flag] = value
            except ValueError:
                parse_error(flag, "Couldn't read argument value from string '" + value + "'")
    return result, bots


class Cell(ctypes.Structure):
    _fields_ = [('owner', ctypes.c_int), ('strength', ctypes.c_int), ('production', ctypes.c_int)]


class Board:
    def __init__(self, seed, slots, w, h, players):
        self.lib = ctypes.CDLL(os.path.join(ROOT, 'build', 'libgame.so'))
        self.cells = ctypes.POINTER(Cell)()
        width, height = ctypes.c_int(), ctypes.c_int()
        self.lib.generate_map.argtypes = [ctypes.c_uint32, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                                          ctypes.c_int, ctypes.POINTER(ctypes.POINTER(Cell)),
                                          ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
        rc = self.lib.generate_map(seed, slots, w & 0xffff, h & 0xffff, players,
                                   ctypes.byref(self.cells), ctypes.byref(width), ctypes.byref(height))
        if rc != 0:
            sys.stdout.flush()
            os.kill(os.getpid(), signal.SIGSEGV)
        self.w, self.h = width.value, height.value
        self.size = self.w * self.h
        self.players = players
        self.moves = (ctypes.c_uint8 * self.size)()

    def production_line(self):
        return ' '.join(str(self.cells[i].production) for i in range(self.size)) + ' \n'

    def frame_line(self):
        vals = []
        owner, run = self.cells[0].owner, 0
        for i in range(self.size):
            cur = self.cells[i].owner
            if cur == owner:
                run += 1
            else:
                vals.extend((str(run), str(owner)))
                owner, run = cur, 1
        vals.extend((str(run), str(owner)))
        vals.extend(str(self.cells[i].strength) for i in range(self.size))
        return ' '.join(vals) + ' \n'

    def snapshot(self):
        return [[[self.cells[y * self.w + x].owner, self.cells[y * self.w + x].strength]
                 for x in range(self.w)] for y in range(self.h)]

    def production_rows(self):
        return [[self.cells[y * self.w + x].production for x in range(self.w)] for y in range(self.h)]

    def forget(self, player):
        for i in range(self.size):
            if self.cells[i].owner == player:
                self.cells[i].owner = 0

    def reset_moves(self):
        ctypes.memset(self.moves, 0, self.size)

    def accept_moves(self, player, line):
        # The wire format allows only decimal digits and ordinary spaces.
        if any(c != ' ' and not ('0' <= c <= '9') for c in line):
            return False
        parts = line.split()
        for i in range(0, len(parts) - 2, 3):
            try:
                x, y, direction = (int(v) for v in parts[i:i+3])
            except ValueError:
                break
            if max(x, y, direction) > 0xffffffff:
                break
            x &= 0xffff
            y &= 0xffff
            if x < self.w and y < self.h:
                pos = y * self.w + x
                if self.cells[pos].owner == player:
                    self.moves[pos] = direction & 255
        return True

    def tick(self):
        self.lib.advance_map(self.cells, self.w, self.h, self.players, self.moves)

    def scores(self):
        area = [0] * (self.players + 1)
        strength = [0] * (self.players + 1)
        production = [0] * (self.players + 1)
        for i in range(self.size):
            c = self.cells[i]
            area[c.owner] += 1
            strength[c.owner] += c.strength
            production[c.owner] += c.production
        return area, strength, production


class Bot:
    def __init__(self, number, command, override):
        self.number, self.command, self.override = number, command, override
        self.name = ''
        self.failed = False
        self.alive = True
        self.last_alive = -1
        self.rank = 0
        self.last_area = self.last_strength = self.last_production = 0
        self.log = []
        self.buffer = b''
        self.proc = subprocess.Popen(['sh', '-c', command], stdin=subprocess.PIPE,
                                     stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                     start_new_session=True, bufsize=0)
        self.fd = self.proc.stdout.fileno()
        os.set_blocking(self.fd, False)

    def send(self, text):
        try:
            self.proc.stdin.write(text.encode('utf-8'))
            self.proc.stdin.flush()
        except (BrokenPipeError, OSError, ValueError):
            pass

    def receive(self, seconds):
        started = time.monotonic()
        deadline = started + seconds if seconds is not None else None
        eof = False
        while True:
            if b'\n' in self.buffer:
                line, self.buffer = self.buffer.split(b'\n', 1)
                if line.endswith(b'\r'):
                    line = line[:-1]
                return line.decode('utf-8', 'replace'), int((time.monotonic()-started)*1000)
            now = time.monotonic()
            if deadline is not None and now >= deadline:
                return None, int((now-started)*1000)
            wait = max(0, deadline-now) if deadline is not None else 3600
            if eof:
                time.sleep(min(wait, .05))
                continue
            ready, _, _ = select.select([self.fd], [], [], wait)
            if not ready:
                continue
            try:
                data = os.read(self.fd, 65536)
            except BlockingIOError:
                continue
            except OSError:
                data = b''
            if not data:
                eof = True
            else:
                self.buffer += data

    def stop(self):
        if not self.proc:
            return
        try:
            os.killpg(self.proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        try:
            self.proc.wait(timeout=.1)
        except subprocess.TimeoutExpired:
            pass
        for handle in (self.proc.stdin, self.proc.stdout):
            try:
                handle.close()
            except OSError:
                pass
        self.proc = None

    def record_response(self, header, line, milliseconds):
        self.log.append(header)
        if line is None:
            self.log.append('\nERRORED!\nNo response received.')
        else:
            self.log.append(line + '\n --- Bot used ' + str(milliseconds) + ' milliseconds ---\n')


def fatal_replay():
    sys.stdout.flush()
    sys.stderr.write("terminate called after throwing an instance of 'std::runtime_error'\n"
                     '  what():  Could not open file for replay\n')
    sys.stderr.flush()
    os.kill(os.getpid(), signal.SIGABRT)


def default_dimensions():
    libc = ctypes.CDLL(None)
    libc.srand(int(time.time()))
    side = 20 + (libc.rand() % 6) * 5
    return side, side


def main():
    opts, params = arguments()
    quiet = opts['q']
    if not params:
        print('Please provide the launch command string for at least one bot.\n'
              'Use the --help flag for usage details.')
        return 1
    if opts['o']:
        if len(params) < 4 or len(params) % 2:
            print('Invalid number of player parameters with override switch enabled.  '
                  'Override intended for server use only.')
            return 1
        commands = params[::2]
        names = params[1::2]
    else:
        commands = params
        names = [None] * len(commands)
    for cmd in commands:
        if not opts['o']:
            print(cmd, flush=True)
        if not quiet:
            print(cmd, flush=True)
    count = len(commands)
    if count > 1 and opts['n'] != 1:
        print('\nOnly single-player mode enables specified n-player maps.  '
              'When entering multiple bots, please do not try to specify n.\n')
        return 1
    slots = count if count > 1 else opts['n']
    if not 1 <= slots <= 6:
        print('\nA map can only accommodate between 1 and 6 players.\n')
        return 1
    seed = opts['s']
    if seed == 0:
        seed = int.from_bytes(os.urandom(4), 'little')
    w, h = opts['d']
    if w == h == 0:
        w, h = default_dimensions()
    board = Board(seed, slots, w, h, count)
    print(board.w, board.h, flush=True)
    stamp = int(time.time())
    replay_name = None
    replay_file = None
    if not opts['r']:
        directory = opts['i']
        if not directory or not os.path.isdir(directory):
            fatal_replay()
        replay_name = directory.rstrip('/') + '/' + str(stamp) + '-' + str(seed) + '.hlt'
        try:
            replay_file = open(replay_name, 'w', encoding='utf-8')
        except OSError:
            fatal_replay()
    bots = []
    try:
        bots = [Bot(i+1, cmd, names[i]) for i, cmd in enumerate(commands)]
        frames = [board.snapshot()] if replay_file else None
        all_moves = [] if replay_file else None
        header = f'{board.w} {board.h} \n' + board.production_line() + board.frame_line()
        for bot in bots:
            bot.send(str(bot.number) + '\n' + header)
            if not quiet:
                print(f'Init Message sent to player {bot.number}.', flush=True)
            line, elapsed = bot.receive(None if opts['t'] else 30)
            bot.record_response(' --- Init ---\n', line, elapsed)
            if line is None:
                if not quiet:
                    print(f'Bot #{bot.number} timeout or error (Unix) 0', flush=True)
                bot.failed = True
                bot.alive = False
                bot.name = 'Timeout'
                board.forget(bot.number)
                bot.stop()
            else:
                bot.name = line
                bot.last_alive = 0
                bot.log.append(SEPARATOR)
                if not quiet:
                    print(f'Init Message received from player {bot.number}, {line}.', flush=True)
            if bot.override is not None:
                bot.name = bot.override
        max_turns = int(10 * math.sqrt(board.size))
        scores = board.scores()
        for bot in bots:
            bot.last_area, bot.last_strength, bot.last_production = (x[bot.number] for x in scores)
        pool = concurrent.futures.ThreadPoolExecutor(max_workers=count)
        for turn in range(1, max_turns+1):
            if not quiet:
                print('Turn ' + str(turn), flush=True)
            board.reset_moves()
            frame_line = board.frame_line()
            active = [bot for bot in bots if bot.alive]
            for bot in active:
                bot.send(frame_line)
            futures = {pool.submit(bot.receive, None if opts['t'] else 1): bot for bot in active}
            for future in concurrent.futures.as_completed(futures):
                bot = futures[future]
                line, elapsed = future.result()
                bot.record_response(f' --- Frame #{turn} ---\n', line, elapsed)
                valid = line is not None and board.accept_moves(bot.number, line)
                if not valid:
                    if line is not None:
                        bot.log.append('ERRORED!\nResponse received (if any):\n' + line)
                    if not quiet:
                        if line is None:
                            print(f'Bot #{bot.number} timeout or error (Unix) 0', flush=True)
                        else:
                            print('Bot sent an invalid character - ejecting from game.', flush=True)
                    bot.failed = True
                    bot.alive = False
                    board.forget(bot.number)
                    bot.stop()
                else:
                    bot.log.append(SEPARATOR)
            if replay_file:
                all_moves.append([[int(board.moves[y*board.w+x]) for x in range(board.w)]
                                  for y in range(board.h)])
            board.tick()
            scores = board.scores()
            survivors = 0
            for bot in bots:
                if scores[0][bot.number]:
                    survivors += 1
                    bot.last_alive = turn
                    bot.last_area, bot.last_strength, bot.last_production = (x[bot.number] for x in scores)
                elif bot.alive:
                    bot.alive = False
                    bot.stop()
            if replay_file:
                frames.append(board.snapshot())
            if count > 1 and survivors <= 1:
                break
        pool.shutdown(wait=True)
        ranked = sorted(bots, key=lambda b: (b.last_alive, b.last_area, b.last_strength, b.number), reverse=True)
        for rank, bot in enumerate(ranked, 1):
            bot.rank = rank
        if replay_file:
            replay = dict(frames=frames, height=board.h, moves=all_moves, num_frames=len(frames),
                          num_players=count, player_names=[b.name for b in bots],
                          productions=board.production_rows(), version=11, width=board.w)
            json.dump(replay, replay_file, separators=(',', ':'), ensure_ascii=False)
            replay_file.close()
            replay_file = None
            if quiet:
                print(replay_name + ' ' + str(seed))
            else:
                print('Map seed was ' + str(seed))
                print('Opening a file at ' + replay_name)
        failed = [b for b in bots if b.failed]
        for bot in failed:
            try:
                with open(f'{bot.number}-{stamp}.log', 'w', encoding='utf-8') as log:
                    log.write(''.join(bot.log))
            except OSError:
                pass
        for bot in bots:
            if quiet:
                print(f'{bot.number} {bot.rank} {bot.last_alive}')
            else:
                print(f'Player #{bot.number}, {bot.name}, came in rank #{bot.rank} '
                      f'and was last alive on frame #{bot.last_alive}!')
        if quiet:
            print(''.join(str(b.number) + ' ' for b in failed) or ' ')
            print(''.join(f'{b.number}-{stamp}.log ' for b in failed) or ' ', end='')
        return 0
    finally:
        for bot in bots:
            bot.stop()
        if replay_file:
            replay_file.close()


if __name__ == '__main__':
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        raise SystemExit(130)
